-- Preserva slugs existentes; novos registros e edições usam a regra revisada.
DROP TRIGGER trg_properties_slug_insert;
DROP TRIGGER trg_properties_slug_update;
CREATE TRIGGER trg_properties_slug_insert AFTER INSERT ON properties
BEGIN
  UPDATE properties SET slug = lower(coalesce(nullif(trim(type),''),'imovel')||'-'||(CASE WHEN lower(trim(type)) IN ('comercial','terreno') THEN (CASE WHEN area_m2>0 THEN CAST(area_m2 AS TEXT)||'m2' ELSE 'area-nao-informada' END) ELSE (CASE WHEN bedrooms=1 THEN '1-quarto' WHEN bedrooms>1 THEN CAST(bedrooms AS TEXT)||'-quartos' ELSE '' END) END)||'-'||trim(neighborhood)||'-'||(CASE WHEN upper(substr(trim(city), -2)) IN ('AC','AL','AP','AM','BA','CE','DF','ES','GO','MA','MT','MS','MG','PA','PB','PR','PE','PI','RJ','RN','RS','RO','RR','SC','SP','SE','TO') AND substr(trim(city),-5,3) = ' - ' THEN substr(trim(city),1,length(trim(city))-5) ELSE trim(city) END)||'-'||(CASE WHEN upper(substr(trim(city), -2)) IN ('AC','AL','AP','AM','BA','CE','DF','ES','GO','MA','MT','MS','MG','PA','PB','PR','PE','PI','RJ','RN','RS','RO','RR','SC','SP','SE','TO') AND substr(trim(city),-5,3) = ' - ' THEN upper(substr(trim(city),-2)) ELSE 'RJ' END)||'-'||code) WHERE id = NEW.id;
  UPDATE properties SET slug = replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(slug,'á','a'),'à','a'),'â','a'),'ã','a'),'ä','a'),'å','a'),'ā','a'),'Á','a'),'À','a'),'Â','a'),'Ã','a'),'Ä','a'),'Å','a'),'Ā','a'),'é','e'),'è','e'),'ê','e'),'ë','e'),'ē','e'),'É','e'),'È','e'),'Ê','e'),'Ë','e'),'Ē','e'),'í','i'),'ì','i'),'î','i'),'ï','i') WHERE id = NEW.id;
  UPDATE properties SET slug = replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(slug,'ī','i'),'Í','i'),'Ì','i'),'Î','i'),'Ï','i'),'Ī','i'),'ó','o'),'ò','o'),'ô','o'),'õ','o'),'ö','o'),'ō','o'),'Ó','o'),'Ò','o'),'Ô','o'),'Õ','o'),'Ö','o'),'Ō','o'),'ú','u'),'ù','u'),'û','u'),'ü','u'),'ū','u'),'Ú','u'),'Ù','u'),'Û','u'),'Ü','u'),'Ū','u') WHERE id = NEW.id;
  UPDATE properties SET slug = replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(slug,'ç','c'),'Ç','c'),'ñ','n'),'Ñ','n'),'ý','y'),'ÿ','y'),'Ý','y'),'Ÿ','y'),' ','-'),'.','-'),',','-'),';','-'),':','-'),'/','-'),'\','-'),'_','-'),'&','-'),'+','-'),'(','-'),')','-'),'[','-'),']','-'),'{','-'),'}','-'),'?','-'),'!','-'),'%','-'),'@','-') WHERE id = NEW.id;
  UPDATE properties SET slug = replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(slug,'#','-'),'"','-'),'’','-'),'–','-'),'—','-'),char(9),'-'),char(10),'-'),char(13),'-'),'''','-'),'--','-'),'--','-'),'--','-'),'--','-'),'--','-'),'--','-'),'--','-'),'--','-'),'--','-') WHERE id = NEW.id;
  UPDATE properties SET slug = trim(slug,'-') WHERE id = NEW.id;
END;

CREATE TRIGGER trg_properties_slug_update AFTER UPDATE OF type, bedrooms, area_m2, neighborhood, city ON properties
BEGIN
  UPDATE properties SET slug = lower(coalesce(nullif(trim(type),''),'imovel')||'-'||(CASE WHEN lower(trim(type)) IN ('comercial','terreno') THEN (CASE WHEN area_m2>0 THEN CAST(area_m2 AS TEXT)||'m2' ELSE 'area-nao-informada' END) ELSE (CASE WHEN bedrooms=1 THEN '1-quarto' WHEN bedrooms>1 THEN CAST(bedrooms AS TEXT)||'-quartos' ELSE '' END) END)||'-'||trim(neighborhood)||'-'||(CASE WHEN upper(substr(trim(city), -2)) IN ('AC','AL','AP','AM','BA','CE','DF','ES','GO','MA','MT','MS','MG','PA','PB','PR','PE','PI','RJ','RN','RS','RO','RR','SC','SP','SE','TO') AND substr(trim(city),-5,3) = ' - ' THEN substr(trim(city),1,length(trim(city))-5) ELSE trim(city) END)||'-'||(CASE WHEN upper(substr(trim(city), -2)) IN ('AC','AL','AP','AM','BA','CE','DF','ES','GO','MA','MT','MS','MG','PA','PB','PR','PE','PI','RJ','RN','RS','RO','RR','SC','SP','SE','TO') AND substr(trim(city),-5,3) = ' - ' THEN upper(substr(trim(city),-2)) ELSE 'RJ' END)||'-'||code) WHERE id = NEW.id;
  UPDATE properties SET slug = replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(slug,'á','a'),'à','a'),'â','a'),'ã','a'),'ä','a'),'å','a'),'ā','a'),'Á','a'),'À','a'),'Â','a'),'Ã','a'),'Ä','a'),'Å','a'),'Ā','a'),'é','e'),'è','e'),'ê','e'),'ë','e'),'ē','e'),'É','e'),'È','e'),'Ê','e'),'Ë','e'),'Ē','e'),'í','i'),'ì','i'),'î','i'),'ï','i') WHERE id = NEW.id;
  UPDATE properties SET slug = replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(slug,'ī','i'),'Í','i'),'Ì','i'),'Î','i'),'Ï','i'),'Ī','i'),'ó','o'),'ò','o'),'ô','o'),'õ','o'),'ö','o'),'ō','o'),'Ó','o'),'Ò','o'),'Ô','o'),'Õ','o'),'Ö','o'),'Ō','o'),'ú','u'),'ù','u'),'û','u'),'ü','u'),'ū','u'),'Ú','u'),'Ù','u'),'Û','u'),'Ü','u'),'Ū','u') WHERE id = NEW.id;
  UPDATE properties SET slug = replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(slug,'ç','c'),'Ç','c'),'ñ','n'),'Ñ','n'),'ý','y'),'ÿ','y'),'Ý','y'),'Ÿ','y'),' ','-'),'.','-'),',','-'),';','-'),':','-'),'/','-'),'\','-'),'_','-'),'&','-'),'+','-'),'(','-'),')','-'),'[','-'),']','-'),'{','-'),'}','-'),'?','-'),'!','-'),'%','-'),'@','-') WHERE id = NEW.id;
  UPDATE properties SET slug = replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(slug,'#','-'),'"','-'),'’','-'),'–','-'),'—','-'),char(9),'-'),char(10),'-'),char(13),'-'),'''','-'),'--','-'),'--','-'),'--','-'),'--','-'),'--','-'),'--','-'),'--','-'),'--','-'),'--','-') WHERE id = NEW.id;
  UPDATE properties SET slug = trim(slug,'-') WHERE id = NEW.id;
END;
